//     We set steps += closeB, so |generated| <= |generatedPrefix| + steps. ✓
//
//   Phase 4 (UnconstrainedStep): steps += 1, |generated| grows by at most 1. ✓
//
//   Phase 7: OpenConstrainedSpan appends "<<" (1 token), steps += 1.
//     CloseSpanWithinBudget same as Phases 3/6. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the very end write: The answer is <<formula>> where formula uses ONLY the template variable names from the problem (e.g., n, frac, count, price, etc.) and Python arithmetic (+,-,*,/,**,()). Use int(expr) when multiplying by a fraction variable. Examples: <<count*(n1+n2+n3+n4+n5)>>, <<n-int(n*frac)>>, <<int(n*frac_1*frac_2)>>, <<n*bill-(m*p1+k*p2)>>, <<multiple*relative_age-orbit_period>>. Write the COMPLETE formula for the final answer.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;
var minSpanTokens: nat := 7;

var freeLimit: nat := (maxSteps * 65) / 100;
if maxSteps > 0 && freeLimit == 0 { freeLimit := 1; }
var phase4Limit: nat := (maxSteps * 82) / 100;
if maxSteps > 0 && phase4Limit == 0 { phase4Limit := 1; }

// Phase 1: Free generation in chunks watching for "<<"
while steps < freeLimit && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeLimit - steps
{
  var chunk: nat := 40;
  if steps + chunk > freeLimit { chunk := freeLimit - steps; }
  if chunk == 0 { break; }
  var cg1, stOp1, stEos1, stUs1 := helpers.UnconstrainedChunk(lm, prompt, generated, chunk, "<<", eosToken);
  generated := cg1;
  steps := steps + stUs1;
  if stEos1 { break; }
  if stOp1 {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// Phase 2: Constrained generation with EOS penalty for short spans
var innerLimit2: nat := 120;
var innerSteps2: nat := 0;
while insideConstrainedOut && steps < maxSteps && innerSteps2 < innerLimit2
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerLimit2 - innerSteps2
{
  if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    var cg2, ci2, cc2 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    hasCompletedSpan := true;
  } else {
    var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next2: Token;
    if |currentConstrainedOut| < minSpanTokens {
      next2 := helpers.PenalizedConstrainedStep(lm, parser, cp2, currentConstrainedOut, [eosToken], 5.0, eosToken);
    } else {
      next2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
    }
    steps := steps + 1;
    innerSteps2 := innerSteps2 + 1;
    if next2 == eosToken { break; }
    var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
    generated := ag2;
    insideConstrainedOut := ai2;
    currentConstrainedOut := ac2;
  }
}

// Phase 3: Force close with ALL remaining budget
if insideConstrainedOut && steps < maxSteps {
  var closeB3 := maxSteps - steps;
  var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB3);
  generated := wg3;
  insideConstrainedOut := wi3;
  currentConstrainedOut := wc3;
  steps := steps + closeB3;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 4: Additional free generation if no span completed yet
while steps < phase4Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase4Limit - steps
{
  var next4 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next4 == eosToken { break; }
  generated := generated + [next4];
  if RenderedEndsWith(generated, "<<") {
    var eg4, ei4, ec4 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg4;
    insideConstrainedOut := ei4;
    currentConstrainedOut := ec4;
  }
}

// Phase 5: Constrained generation for span opened in Phase 4
var innerLimit5: nat := 120;
var innerSteps5: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps5 < innerLimit5
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerLimit5 - innerSteps5
{
  if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    var cg5, ci5, cc5 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    generated := cg5;
    insideConstrainedOut := ci5;
    currentConstrainedOut := cc5;
    hasCompletedSpan := true;
  } else {
    var cp5 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next5: Token;
    if |currentConstrainedOut| < minSpanTokens {
      next5 := helpers.PenalizedConstrainedStep(lm, parser, cp5, currentConstrainedOut, [eosToken], 5.0, eosToken);
    } else {
      next5 := helpers.ConstrainedStep(lm, parser, cp5, currentConstrainedOut, eosToken);
    }
    steps := steps + 1;
    innerSteps5 := innerSteps5 + 1;
    if next5 == eosToken { break; }
    var ag5, ai5, ac5 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5);
    generated := ag5;
    insideConstrainedOut := ai5;
    currentConstrainedOut := ac5;
  }
}

// Phase 6: Force close Phase 4/5 span with ALL remaining budget
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var closeB6 := maxSteps - steps;
  var wg6, wi6, wc6 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB6);
  generated := wg6;
  insideConstrainedOut := wi6;
  currentConstrainedOut := wc6;
  steps := steps + closeB6;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 7: Force open a span if none completed, then close with all remaining budget
if !insideConstrainedOut && !hasCompletedSpan && steps + 2 <= maxSteps {
  var fg7, fi7, fc7 := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg7;
  insideConstrainedOut := fi7;
  currentConstrainedOut := fc7;
  steps := steps + 1;

  var innerLimit7: nat := 60;
  var innerSteps7: nat := 0;
  while insideConstrainedOut && steps < maxSteps && innerSteps7 < innerLimit7
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps + innerLimit7 - innerSteps7
  {
    if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
      var cg7, ci7, cc7 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      steps := steps + 1;
      generated := cg7;
      insideConstrainedOut := ci7;
      currentConstrainedOut := cc7;
      hasCompletedSpan := true;
    } else {
      var cp7 := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next7: Token;
      if |currentConstrainedOut| < minSpanTokens {
        next7 := helpers.PenalizedConstrainedStep(lm, parser, cp7, currentConstrainedOut, [eosToken], 5.0, eosToken);
      } else {
        next7 := helpers.ConstrainedStep(lm, parser, cp7, currentConstrainedOut, eosToken);
      }
      steps := steps + 1;
      innerSteps7 := innerSteps7 + 1;
      if next7 == eosToken { break; }
      var ag7, ai7, ac7 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next7);
      generated := ag7;
      insideConstrainedOut := ai7;
      currentConstrainedOut := ac7;
    }
  }

  if insideConstrainedOut && steps < maxSteps {
    var closeB7 := maxSteps - steps;
    var wg7, wi7, wc7 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB7);
    generated := wg7;
    insideConstrainedOut := wi7;
    currentConstrainedOut := wc7;
    steps := steps + closeB7;
  }
}

cost := steps;
